<?php require 'config/bootstrap.php'; require_login();
$s=db()->prepare("SELECT p.*,c.title FROM payments p JOIN contracts c ON c.id=p.contract_id WHERE c.user_id=? ORDER BY p.due_date");$s->execute([uid()]);$r=$s->fetchAll();
page_head('Payments'); ?><h1 class="h3 mb-3">Payments</h1><div class="cardx table-responsive"><?php if(!$r):?><div class="empty">No payments scheduled. Add them from a contract page.</div><?php else:?><table class="table"><tr><th>Contract</th><th>Due</th><th>Expected</th><th>Paid</th><th>Outstanding</th><th>Status</th></tr><?php foreach($r as $x):?><tr><td><a href="contract.php?id=<?=$x['contract_id']?>"><?=e($x['title'])?></a></td><td><?=e($x['due_date'])?></td><td><?=e($x['currency'].' '.$x['expected_amount'])?></td><td><?=e($x['paid_amount']??'—')?></td><td><?=e(bcsub($x['expected_amount'],$x['paid_amount']??'0',2))?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table><?php endif;?></div><?php page_foot();
